import os
from IQCommon.common import NOTEBOOK_DIR_PATH
from IQCommon.exception import get_traceback_message
from IQCommon.logger import strategy_log
from IQCommon.util.wrapper_utils import check_arg
@check_arg
def create_dir(user_path):
    """
    研究路径创建目录
    :param user_path: 待创建相对路径
    :type user_path: str
    :return: 是否创建成功
    :rtype: bool
    """
    if user_path is None:
        strategy_log.error('user_path入参为空')
        return False
    else:
        notebook_user_path = os.path.join(NOTEBOOK_DIR_PATH, user_path)
        try:
            os.makedirs(notebook_user_path, exist_ok=True)
            os.chmod(notebook_user_path, 511)
            strategy_log.info('%s目录创建成功' % user_path)
            return True
        except BaseException:
            strategy_log.error(f'{user_path!s}目录创建失败，错误原因：{get_traceback_message()!s}')
            return False
